var exec = require( "child_process" ).exec;

module.exports = function(grunt) {
"use strict";

grant.registerTask( "check-modules", "Run this before anything else that loads local modules to verify they're installed", function() {
	var done = this.async();
	exec( "npm ls", function( err ) {
		if ( err ) {
			done( err );
			return;
		}
		grunt.verbose.ok();
		done();
	});
});

};
